class TextEditor {
    std::string left;
    std::string right;
public:
    TextEditor() {}

    void addText(std::string text) {
        left += text;
    }

    int deleteText(int k) {
        int cnt = std::min((int)left.size(), k);
        left.resize(left.size() - cnt);
        return cnt;
    }

    std::string cursorLeft(int k) {
        int cnt = std::min((int)left.size(), k);
        while (cnt--) {
            right.push_back(left.back());
            left.pop_back();
        }
        int len = std::min(10, (int)left.size());
        return left.substr(left.size() - len);
    }

    std::string cursorRight(int k) {
        int cnt = std::min((int)right.size(), k);
        while (cnt--) {
            left.push_back(right.back());
            right.pop_back();
        }
        int len = std::min(10, (int)left.size());
        return left.substr(left.size() - len);
    }
};

class TextEditor {
    private StringBuilder left = new StringBuilder();
    private StringBuilder right = new StringBuilder();

    public TextEditor() {}

    public void addText(String text) {
        left.append(text);
    }

    public int deleteText(int k) {
        int cnt = Math.min(left.length(), k);
        left.setLength(left.length() - cnt);
        return cnt;
    }

    public String cursorLeft(int k) {
        int cnt = Math.min(left.length(), k);
        while (cnt-- > 0) {
            right.append(left.charAt(left.length() - 1));
            left.setLength(left.length() - 1);
        }
        int len = Math.min(10, left.length());
        return left.substring(left.length() - len);
    }

    public String cursorRight(int k) {
        int cnt = Math.min(right.length(), k);
        while (cnt-- > 0) {
            left.append(right.charAt(right.length() - 1));
            right.setLength(right.length() - 1);
        }
        int len = Math.min(10, left.length());
        return left.substring(left.length() - len);
    }
}

var TextEditor = function() {
    this.left = [];
    this.right = [];
};

TextEditor.prototype.addText = function(text) {
    for (let i = 0; i < text.length; i++) this.left.push(text[i]);
};

TextEditor.prototype.deleteText = function(k) {
    const cnt = Math.min(this.left.length, k);
    this.left.length -= cnt;
    return cnt;
};

TextEditor.prototype.cursorLeft = function(k) {
    let cnt = Math.min(this.left.length, k);
    while (cnt-- > 0) {
        this.right.push(this.left.pop());
    }
    const start = Math.max(0, this.left.length - 10);
    return this.left.slice(start).join("");
};

TextEditor.prototype.cursorRight = function(k) {
    let cnt = Math.min(this.right.length, k);
    while (cnt-- > 0) {
        this.left.push(this.right.pop());
    }
    const start = Math.max(0, this.left.length - 10);
    return this.left.slice(start).join("");
};
